package ai.blackware.insfollow

import android.test.InstrumentationTestCase
import ai.blackware.insfollow.data.*
import ai.blackware.insfollow.model.*
import org.json.JSONObject

@Suppress("DEPRECATION")
class StoreDeviceTest : InstrumentationTestCase() {
    private lateinit var store: Store
    private val filename="fixture-test.db"
    private val fixture="""{"favorite_page_pref":"[{\"name\":\"One\",\"items\":[{\"pageId\":\"fiction.one\",\"name\":\"Ü One\"},{\"pageId\":\"fiction.two\",\"name\":\"Two\"}]},{\"name\":\"Two\",\"items\":[{\"pageId\":\" FICTION.ONE \",\"name\":\"Duplicate\"}]}]","other":17}"""
    override fun setUp() { super.setUp(); instrumentation.targetContext.deleteDatabase(filename); store=Store(instrumentation.targetContext,filename); store.import(FavoritesCodec.parse(fixture),"fiction.json"); store.selectAll(true) }
    override fun tearDown() { store.close(); instrumentation.targetContext.deleteDatabase(filename); super.tearDown() }
    fun testMembershipAndRepeatedImport() { store.import(FavoritesCodec.parse(fixture),"fiction.json"); assertEquals(2,store.accounts().size); assertEquals(2,store.folders().size); assertEquals(3 to 2,store.selectedCounts()) }
    fun testOrderAndPositionSurviveRestart() { val id=store.createQueue(); val before=JSONObject(store.backup()).getJSONArray("queue").toString(); val work=store.acquire(id)!!; store.finish(work,Verdict(Status.ALREADY,"FOLLOWING_VERIFIED"),"FOLLOWING"); store.close(); store=Store(instrumentation.targetContext,filename); assertEquals(1,store.queueStats(id)["DONE"]); assertEquals(2,JSONObject(store.backup()).getJSONArray("queue").length()); val next=store.acquire(id)!!; assertTrue(work.key!=next.key); assertTrue(before.contains(next.key)) }
    fun testQueueDoesNotReshuffleOnCreate() { val id=store.createQueue(); val before=JSONObject(store.backup()).getJSONArray("queue").toString(); assertEquals(id,store.createQueue()); assertEquals(before,JSONObject(store.backup()).getJSONArray("queue").toString()) }
    fun testInterruptedOperationBecomesUncertain() { val id=store.createQueue(); val work=store.acquire(id)!!; store.recover(); assertNull(store.current()); assertEquals(Status.UNCERTAIN,store.accounts().first { it.key==work.key }.status); assertEquals("INTERRUPTED_VERIFICATION",store.accounts().first { it.key==work.key }.reason) }
    fun testConfirmedResultPreservedDuringInterruptedRecheck() { val id=store.createQueue(); val work=store.acquire(id)!!; store.finish(work,Verdict(Status.SUCCESS,"FOLLOWING_VERIFIED"),"FOLLOWING"); store.recheck(work.key); store.acquire(id)?.let { if(it.key!=work.key) { store.finish(it,Verdict(Status.REQUESTED,"FOLLOW_REQUEST_PENDING"),"REQUESTED"); store.acquire(id) } }; store.recover(); assertEquals(Status.SUCCESS,store.accounts().first { it.key==work.key }.status) }
    fun testReimportPreservesProgress() { val id=store.createQueue(); val work=store.acquire(id)!!; store.finish(work,Verdict(Status.FAILURE,"PROFILE_NOT_FOUND"),"UNAVAILABLE"); store.import(FavoritesCodec.parse(fixture),"again.json"); assertEquals(Status.FAILURE,store.accounts().first { it.key==work.key }.status); assertEquals(1,store.queueStats(id)["DONE"]) }
    fun testCompletedExcludedInNextSession() { val id=store.createQueue(); repeat(2) { store.finish(store.acquire(id)!!,Verdict(Status.ALREADY,"FOLLOWING_VERIFIED"),"FOLLOWING") }; assertNull(store.acquire(id)); val next=store.createQueue(); assertTrue(store.queueStats(next).isEmpty()) }
    fun testPauseAndStopPreserveCodes() { val id=store.createQueue(); val before=store.accounts(); store.setSession(id,"PAUSED"); store.setSession(id,"STOPPED"); assertEquals(before,store.accounts()); assertEquals(id,store.createQueue()) }
    fun testWriteFailureRollsBackResultAndQueue() { val id=store.createQueue(); val work=store.acquire(id)!!; store.writableDatabase.execSQL("CREATE TRIGGER reject_write BEFORE UPDATE ON accounts BEGIN SELECT RAISE(ABORT, 'fixture'); END"); try { store.finish(work,Verdict(Status.SUCCESS,"FOLLOWING_VERIFIED"),"FOLLOWING"); fail() } catch(_: android.database.SQLException) {} finally { store.writableDatabase.execSQL("DROP TRIGGER reject_write") }; assertNotNull(store.current()); assertEquals(Status.UNPROCESSED,store.accounts().first { it.key==work.key }.status); assertEquals(1,store.queueStats(id)["INFLIGHT"]) }
    fun testBackupRestoreAndAtomicRejection() { store.settings(mapOf("min" to "77")); val backup=store.backup(); store.restore(backup); assertEquals("77",store.setting("min","")); val malformed=JSONObject(backup); malformed.getJSONArray("memberships").getJSONObject(0).put("accountKey","missing"); try { store.restore(malformed.toString()); fail() } catch(_: Exception) {}; assertEquals(2,store.accounts().size); assertEquals(3 to 2,store.selectedCounts()) }
    fun testAnnotatedExportProvenancePreventsDoubleSuffix() { val id=store.createQueue(); repeat(2) { store.finish(store.acquire(id)!!,Verdict(Status.SUCCESS,"FOLLOWING_VERIFIED"),"FOLLOWING") }; val exported=store.annotated(false); store.import(FavoritesCodec.parse(exported),"annotated.json"); assertEquals(exported,store.annotated(false)); assertEquals(2,store.folders().size); assertEquals(17,JSONObject(exported).getInt("other")) }
    fun testTimeoutNeverDefiniteFailure() { val id=store.createQueue(); val work=store.acquire(id)!!; store.finish(work,Verdict(Status.UNCERTAIN,"VERIFICATION_TIMEOUT"),"UNKNOWN"); assertEquals(Status.UNCERTAIN,store.accounts().first { it.key==work.key }.status) }
    fun testResultIdempotence() { val id=store.createQueue(); val work=store.acquire(id)!!; repeat(2) { store.finish(work,Verdict(Status.REQUESTED,"FOLLOW_REQUEST_PENDING"),"REQUESTED") }; assertEquals(1,store.countProcessed(id)); assertEquals(1,store.accounts().first { it.key==work.key }.attempts) }
}
